-- Nigeria location source: GeoNames, CC BY 4.0; filtered and transformed for this application.
-- 37 administrative areas and 61,041 mapped populated places.
-- This source contains populated places, not a verified exhaustive list of cities or LGAs.
-- Import once into a new/empty schema. No DROP/DELETE statements. MySQL 5.7+/MariaDB.
SET NAMES utf8mb4;
SET @ng_previous_sql_mode=@@SESSION.sql_mode;
SET SESSION sql_mode='NO_BACKSLASH_ESCAPES,STRICT_TRANS_TABLES';
CREATE TABLE IF NOT EXISTS ng_states (id VARCHAR(80) PRIMARY KEY, name VARCHAR(80) NOT NULL, capital VARCHAR(100) NOT NULL, type VARCHAR(40) NOT NULL, zone VARCHAR(30) NOT NULL, geonames_id BIGINT NOT NULL UNIQUE, geonames_admin1_code VARCHAR(10) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ng_places (id VARCHAR(30) PRIMARY KEY, geonames_id BIGINT NOT NULL UNIQUE, state_id VARCHAR(80) NOT NULL, name VARCHAR(200) NOT NULL, ascii_name VARCHAR(200) NOT NULL, feature_code VARCHAR(10) NOT NULL, latitude DOUBLE NOT NULL, longitude DOUBLE NOT NULL, population BIGINT NULL, is_state_capital INTEGER NOT NULL, is_shortlisted INTEGER NOT NULL, alternate_names_json TEXT NOT NULL, quality_flags_json TEXT NOT NULL, source_timezone VARCHAR(80) NULL, source_modified_date VARCHAR(10) NOT NULL, geonames_admin2_code VARCHAR(80) NULL, FOREIGN KEY (state_id) REFERENCES ng_states(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX ng_places_state_name ON ng_places(state_id,name);
CREATE INDEX ng_places_state_shortlist ON ng_places(state_id,is_shortlisted);
START TRANSACTION;
COMMIT;
SET SESSION sql_mode=@ng_previous_sql_mode;


-- Keep Nigeria's state IDs available to existing customer, supplier and address forms.
-- The complete searchable place source lives in ng_places; legacy city selectors use its shortlist.
SELECT ids.next_id,'Nigeria',CURDATE(),1
FROM (SELECT COALESCE(MAX(id),0)+1 AS next_id FROM db_country) ids
WHERE NOT EXISTS (SELECT 1 FROM db_country WHERE UPPER(TRIM(country))='NIGERIA');
SET @ng_country_id=(SELECT MIN(id) FROM db_country WHERE UPPER(TRIM(country))='NIGERIA');
SELECT NULL,CONCAT('NG',s.geonames_admin1_code),IF(s.id='ng-federal-capital-territory','FCT',s.name),'NG',@ng_country_id,'Nigeria',CURDATE(),NULL,1
FROM ng_states s
WHERE NOT EXISTS (SELECT 1 FROM db_states d WHERE d.store_id IS NULL AND UPPER(TRIM(d.country))='NIGERIA' AND d.state_code=CONCAT('NG',s.geonames_admin1_code));
